Read file /Users/ajeet/Projects/Hackathons/Sheridan Datathon 2026/src/dashScan.test.ts, lines 1-197
1: import { readdirSync, readFileSync, statSync } from 'node:fs'
2: import { join } from 'node:path'
3: import { describe, expect, it } from 'vitest'
4: 
5: /**
6:  * Content rule scan for the Phase E2 sources (docs/architecture.md): no
7:  * em dash, en dash, minus sign, double hyphen, or spaced hyphen may appear
8:  * in anything this phase writes (UI copy, comments, JSX text). The three
9:  * dash code points are checked across the whole file because they can
10:  * never be valid TypeScript; the hyphen patterns are checked only in
11:  * prose (comments, string and template literals, JSX text) because a
12:  * spaced hyphen is a legitimate way to write subtraction in code. The
13:  * patterns below are assembled from code points so this file passes its
14:  * own scan, and the numeric minus inside formatted money stays allowed
15:  * because it is a formatted number, not copy.
16:  */
17: 
18: const EM_DASH = String.fromCharCode(0x2014)
19: const EN_DASH = String.fromCharCode(0x2013)
20: const MINUS_SIGN = String.fromCharCode(0x2212)
21: const DOUBLE_HYPHEN = '-'.repeat(2)
22: const SPACED_HYPHEN = [' ', '-', ' '].join('')
23: 
24: /** Prose characters a JSX text node may hold before we read it as copy. */
25: const PROSE = /^[\p{L}\p{N} .,:()'"/!?&+%-]+$/u
26: 
27: /** E2 files that do not live in an auto scanned directory. */
28: const EXPLICIT_FILES: readonly string[] = [
29:   'src/App.tsx',
30:   'src/app.smoke.test.ts',
31:   'src/dashScan.test.ts',
32:   'src/data/profiles.ts',
33:   'src/data/profiles.test.ts',
34:   'src/lib/format.ts',
35:   'src/lib/metrics.ts',
36:   'src/lib/planText.ts',
37:   'src/lib/planText.test.ts',
38:   'src/lib/shockPresets.ts',
39:   'src/lib/shocks.golden.test.ts',
40:   'src/lib/shocks.test.ts',
41:   'src/lib/shocks.ts',
42:   'src/lib/verdict.ts',
43:   'src/lib/verdict.test.ts',
44: ]
45: 
46: /** Directories whose every source file is part of this phase. */
47: const AUTO_DIRS: readonly string[] = ['src/state', 'src/components/console']
48: 
49: /** Stylesheets written this phase, scanned without the double hyphen rule. */
50: const CSS_FILES: readonly string[] = ['src/index.css']
51: 
52: function listDir(directory: string): string[] {
53:   const out: string[] = []
54:   for (const name of readdirSync(directory)) {
55:     const path = join(directory, name)
56:     if (statSync(path).isDirectory()) {
57:       out.push(...listDir(path))
58:     } else if (/\.(ts|tsx)$/.test(name)) {
59:       out.push(path)
60:     }
61:   }
62:   return out
63: }
64: 
65: function targetFiles(): string[] {
66:   const paths = [...EXPLICIT_FILES]
67:   for (const directory of AUTO_DIRS) {
68:     paths.push(...listDir(directory))
69:   }
70:   return [...new Set(paths)].sort()
71: }
72: 
73: interface Prose {
74:   file: string
75:   line: number
76:   chunk: string
77:   where: string
78: }
79: 
80: function lineOf(text: string, index: number): number {
81:   return text.slice(0, index).split('\n').length
82: }
83: 
84: /** Pull every piece of prose out of one source file. */
85: function proseOf(file: string, text: string): Prose[] {
86:   const prose: Prose[] = []
87:   let rest = text
88: 
89:   const push = (chunk: string, index: number, where: string): void => {
90:     prose.push({ file, line: lineOf(text, index), chunk, where })
91:   }
92: 
93:   // Block comments first, then line comments, so an apostrophe inside a
94:   // comment can never open a string that swallows real code.
95:   rest = rest.replace(/\/\*[\s\S]*?\*\//g, (chunk, index: number) => {
96:     push(chunk, index, 'block comment')
97:     return ' '
98:   })
99:   rest = rest.replace(/\/\/[^\n]*/g, (chunk, index: number) => {
100:     push(chunk, index, 'line comment')
101:     return ' '
102:   })
103: 
104:   const stringPattern = /'(?:[^'\\\n]|\\.)*'|"(?:[^"\\\n]|\\.)*"|`(?:[^`\\]|\\.)*`/g
105:   let match: RegExpExecArray | null
106:   while ((match = stringPattern.exec(rest)) !== null) {
107:     // Template expressions are code, not copy.
108:     const chunk = match[0].replace(/\$\{[^}]*\}/g, '')
109:     push(chunk, match.index, 'string literal')
110:   }
111:   rest = rest.replace(stringPattern, ' ')
112: 
113:   // JSX text nodes: prose between a tag close and the next tag open.
114:   const jsxPattern = />([^<>{}]+)</g
115:   while ((match = jsxPattern.exec(rest)) !== null) {
116:     const chunk = match[1] ?? ''
117:     if (PROSE.test(chunk) && /[A-Za-z]/.test(chunk)) {
118:       push(chunk, match.index, 'jsx text')
119:     }
120:   }
121: 
122:   return prose
123: }
124: 
125: function violationsIn(chunk: string): string[] {
126:   const problems: string[] = []
127:   if (chunk.includes(EM_DASH)) {
128:     problems.push('em dash')
129:   }
130:   if (chunk.includes(EN_DASH)) {
131:     problems.push('en dash')
132:   }
133:   if (chunk.includes(MINUS_SIGN)) {
134:     problems.push('minus sign')
135:   }
136:   if (chunk.includes(DOUBLE_HYPHEN)) {
137:     problems.push('double hyphen')
138:   }
139:   if (chunk.includes(SPACED_HYPHEN)) {
140:     problems.push('spaced hyphen')
141:   }
142:   return problems
143: }
144: 
145: describe('content rule: dash scan over the Phase E2 sources', () => {
146:   const files = targetFiles()
147: 
148:   it('covers every file this phase wrote', () => {
149:     expect(files).toContain('src/components/console/ConsoleView.tsx')
150:     expect(files).toContain('src/state/consoleStore.ts')
151:     expect(files.length).toBeGreaterThanOrEqual(20)
152:   })
153: 
154:   it('keeps dash code points and dash copy out of every file', () => {
155:     const found: string[] = []
156:     for (const file of files) {
157:       const text = readFileSync(file, 'utf8')
158:       const lines = text.split('\n')
159:       lines.forEach((line, index) => {
160:         for (const character of [EM_DASH, EN_DASH, MINUS_SIGN]) {
161:           if (line.includes(character)) {
162:             found.push(`${file}:${index + 1}: dash code point in source`)
163:           }
164:         }
165:       })
166:       for (const entry of proseOf(file, text)) {
167:         for (const problem of violationsIn(entry.chunk)) {
168:           const excerpt = entry.chunk.trim().slice(0, 120)
169:           found.push(`${file}:${entry.line}: ${problem} in ${entry.where}: ${excerpt}`)
170:         }
171:       }
172:     }
173:     expect(found).toEqual([])
174:   })
175: 
176:   it('keeps the console stylesheet free of dash copy', () => {
177:     // CSS is scanned too, with one exception: a custom property name
178:     // begins with two hyphens, which is syntax rather than copy, and CSS
179:     // holds no user facing copy beyond the comments checked here.
180:     const found: string[] = []
181:     for (const file of CSS_FILES) {
182:       const text = readFileSync(file, 'utf8')
183:       const lines = text.split('\n')
184:       lines.forEach((line, index) => {
185:         for (const character of [EM_DASH, EN_DASH, MINUS_SIGN]) {
186:           if (line.includes(character)) {
187:             found.push(`${file}:${index + 1}: dash code point in source`)
188:           }
189:         }
190:         if (line.includes(SPACED_HYPHEN)) {
191:           found.push(`${file}:${index + 1}: spaced hyphen: ${line.trim().slice(0, 120)}`)
192:         }
193:       })
194:     }
195:     expect(found).toEqual([])
196:   })
197: })

